ect_option":null,"answer":"Polite greeting; position name; day, date and time; full venue with landmark; documents to bring; contact person and number; sign-off.","marks":10,"difficulty":"easy","department":"","designation":"","topic":"Communication","round":"any","is_active":true,"created_by_name":"Tareq Azij","created_at":"2026-10-20T04:00:00.000Z","kind":"written","question":"Write a short email to a candidate inviting them to a primary interview. Include the day, time, venue and what to bring."},{"id":"22d535b7-60b6-4753-a078-35a378f4af72","options":[],"correct_option":null,"answer":"Find the real delay; re-plan production with the factory; check air freight or partial shipment; inform the buyer early with a revised plan; record the cause.","marks":15,"difficulty":"hard","department":"Merchandising","designation":"Merchandiser","topic":"Garments","round":"any","is_active":true,"created_by_name":"Tareq Azij","created_at":"2026-10-20T04:00:00.000Z","kind":"written","question":"A buyer's shipment date is at risk because fabric arrived late. Explain how you would handle it."},{"id":"125bccf1-4903-45a4-aada-76934064bd5e","options":[],"correct_option":null,"answer":"Clear and brief; links past work to this role; knows something about the company.","marks":10,"difficulty":"medium","department":"","designation":"","topic":"Introduction","round":"primary","is_active":true,"created_by_name":"Tareq Azij","created_at":"2026-10-20T04:00:00.000Z","kind":"interview","question":"Tell us about yourself and why you applied for this position."},{"id":"13d28c67-72c7-4b05-ab25-84d0339f1239","options":[],"correct_option":null,"answer":"A real example; their own part in it; a measurable result.","marks":10,"difficulty":"medium","department":"","designation":"","topic":"Experience","round":"primary","is_active":true,"created_by_name":"Tareq Azij","created_at":"2026-10-20T04:00:00.000Z","kind":"interview","question":"Describe a problem at your last job that you solved. What did you do, and what was the result?"},{"id":"e0f12899-eaff-40f7-aa01-5841a9e07f22","options":[],"correct_option":null,"answer":"Realistic plan; fits the career path here; intends to stay.","marks":10,"difficulty":"easy","department":"","designation":"","topic":"Attitude","round":"final","is_active":true,"created_by_name":"Tareq Azij","created_at":"2026-10-20T04:00:00.000Z","kind":"interview","question":"Where do you see yourself in three years, and how would this job help?"},{"id":"c1e19940-8e1e-4ebc-ab62-daff69775803","options":[],"correct_option":null,"answer":"Listen and record; stay neutral; hear the supervisor; check facts; follow the company grievance procedure; keep it confidential; follow up.","marks":10,"difficulty":"hard","department":"HR & Admin","designation":"","topic":"HR basics","round":"final","is_active":true,"created_by_name":"Tareq Azij","created_at":"2026-10-20T04:00:00.000Z","kind":"interview","question":"An employee complains that a supervisor treats them unfairly. How would you handle it?"}]}$sample$, '@@agm@@', agm::text), '@@nafis@@', nafis::text), '@@mili@@', mili::text)::jsonb;

  insert into public.designations (id, title, department, company, sanctioned, filled, is_active, created_at)
    select x.id, x.title, x.department, x.company, x.sanctioned, x.filled, x.is_active, x.created_at from jsonb_populate_recordset(null::public.designations, d -> 'designations') x
    on conflict do nothing;
  insert into public.requisitions (id, designation_id, designation, department, company, vacancies, priority, employment_type, location, hiring_manager, requested_by, budget_min, budget_max, target_date, status, justification, job_description, created_at, filled_at, unit, section, subsection, vacancy_type, replacing, requisition_date, approved_on, offer_date, expected_joining, selected_names, remarks, sheet_key, sheet_data)
    select x.id, (select id from public.designations where id = x.designation_id), x.designation, x.department, x.company, x.vacancies, x.priority, x.employment_type, x.location, x.hiring_manager, x.requested_by, x.budget_min, x.budget_max, x.target_date, x.status, x.justification, x.job_description, x.created_at, x.filled_at, x.unit, x.section, x.subsection, x.vacancy_type, x.replacing, x.requisition_date, x.approved_on, x.offer_date, x.expected_joining, x.selected_names, x.remarks, x.sheet_key, x.sheet_data from jsonb_populate_recordset(null::public.requisitions, d -> 'requisitions') x
    on conflict do nothing;
  insert into public.job_postings (id, requisition_id, media, url, posted_on, closes_on, cost, status, notes, created_at)
    select x.id, x.requisition_id, x.media, x.url, x.posted_on, x.closes_on, x.cost, x.status, x.notes, x.created_at from jsonb_populate_recordset(null::public.job_postings, d -> 'job_postings') x
    on conflict do nothing;
  insert into public.cv_buckets (id, requisition_id, designation, department, company, color, status, accepting_applications, description, created_at, unit, section, subsection)
    select x.id, x.requisition_id, x.designation, x.department, x.company, x.color, x.status, x.accepting_applications, x.description, x.created_at, x.unit, x.section, x.subsection from jsonb_populate_recordset(null::public.cv_buckets, d -> 'cv_buckets') x
    on conflict do nothing;
  insert into public.candidates (job_posting_id, source, received_at, alt_phone, address, permanent_address, date_of_birth, father_name, mother_name, spouse_name, gender, marital_status, religion, nationality, blood_group, national_id, passport_no, tin_no, linkedin, current_designation, current_company, industry, total_experience_years, present_salary, expected_salary, notice_period, career_summary, education, experience, training, skills, languages, references_list, sections, raw_text, cv_path, cv_file_name, photo_path, parse_method, parse_warnings, screening_status, screening_note, assigned_to, handover_note, handed_over_by, handed_over_at, call_status, call_note, followup_on, followup_time, called_at, called_by, call_date, call_time, confirmed_date, confirmed_time, call_rejected_date, call_rejected_time, message_status, message_sent_at, message_channel, primary_status, primary_date, primary_time, primary_interviewer, primary_score, primary_feedback, primary_panel, secondary_message_status, secondary_message_sent_at, secondary_status, secondary_date, secondary_time, secondary_interviewer, secondary_score, secondary_feedback, secondary_panel, selection_category, final_decision, decision_date, decision_time, informed_date, informed_time, decided_by, decided_at, review_seconds, review_count, joining_status, joining_date, joining_time, joining_call_date, joining_call_time, joining_confirmed_date, joining_confirmed_time, joining_remarks, offered_salary, employee_code, probation_period, reporting_to, documents_received, offer_sent_at, selected_at, created_at, id, bucket_id, full_name, phone, email)
    select x.job_posting_id, x.source, x.received_at, x.alt_phone, x.address, x.permanent_address, x.date_of_birth, x.father_name, x.mother_name, x.spouse_name, x.gender, x.marital_status, x.religion, x.nationality, x.blood_group, x.national_id, x.passport_no, x.tin_no, x.linkedin, x.current_designation, x.current_company, x.industry, x.total_experience_years, x.present_salary, x.expected_salary, x.notice_period, x.career_summary, x.education, x.experience, x.training, x.skills, x.languages, x.references_list, x.sections, x.raw_text, x.cv_path, x.cv_file_name, x.photo_path, x.parse_method, x.parse_warnings, x.screening_status, x.screening_note, x.assigned_to, x.handover_note, x.handed_over_by, x.handed_over_at, x.call_status, x.call_note, x.followup_on, x.followup_time, x.called_at, x.called_by, x.call_date, x.call_time, x.confirmed_date, x.confirmed_time, x.call_rejected_date, x.call_rejected_time, x.message_status, x.message_sent_at, x.message_channel, x.primary_status, x.primary_date, x.primary_time, x.primary_interviewer, x.primary_score, x.primary_feedback, x.primary_panel, x.secondary_message_status, x.secondary_message_sent_at, x.secondary_status, x.secondary_date, x.secondary_time, x.secondary_interviewer, x.secondary_score, x.secondary_feedback, x.secondary_panel, x.selection_category, x.final_decision, x.decision_date, x.decision_time, x.informed_date, x.informed_time, x.decided_by, x.decided_at, x.review_seconds, x.review_count, x.joining_status, x.joining_date, x.joining_time, x.joining_call_date, x.joining_call_time, x.joining_confirmed_date, x.joining_confirmed_time, x.joining_remarks, x.offered_salary, x.employee_code, x.probation_period, x.reporting_to, x.documents_received, x.offer_sent_at, x.selected_at, x.created_at, x.id, x.bucket_id, x.full_name, x.phone, x.email from jsonb_populate_recordset(null::public.candidates, d -> 'candidates') x
    on conflict do nothing;

  -- Adding postings and candidates wrote alerts and "received by the company form"; the sample's own history replaces them.
  -- Those were all written just now, in this transaction, so now() picks out exactly them.
  delete from public.candidate_events where candidate_id = any (array['001359f1-79df-42f9-aaef-804a442f68d3', '099c21ca-0fbc-4343-a4b1-74b2a1959922', 'de3c19df-c105-442a-a9d5-19aa5771e901', 'de4c1136-4311-43f7-a7f9-e82f572005a3', '28d0d866-13c0-410f-ad6e-1fb940232448', '0d14c68f-997b-4f68-a51b-1693be2878c3', 'c946d3e2-b934-4104-a60a-58f38f268772', '1f59bb9d-5bb6-4af7-a012-6ca68e2f0e13', '618f90ca-1774-4d5f-abe2-03cc20da4839', '866716f8-0b12-4977-a581-5ecf14fb52ad', 'c673e24c-2f0d-44d2-af96-7e471c38b21f', 'fe97d20b-4b83-49ef-abea-c5098b071412', 'f6dd92b1-9de1-4928-a6d5-22169a7bd827', 'b58dcfa0-4c5e-424c-aaf2-232dd02038f4', 'a4d76957-494d-4a9b-a82c-59eb12a4e031', 'cd8e831d-081c-4952-adff-fce441f0eb43', 'cd061b53-3db6-4152-a790-f6b4166e876a', 'cc44c42c-ad2a-40c2-a0ef-941194326da9', 'c3697306-bbe1-4773-a28b-a592b70f099c', 'ffe34774-f99f-42ab-a36b-b5947a1a8f87', 'd6a3e921-2313-43e7-a877-992c9963d25e', 'f2533b7e-eb69-41f5-a918-0a2f203be2bc', 'b5b78f13-1d3a-4d25-a69e-0f5b4e9b56bd']::uuid[]);
  delete from public.notifications where created_at = now();

  insert into public.candidate_events (id, candidate_id, field, from_value, to_value, actor_name, actor_id, created_at)
    select x.id, x.candidate_id, x.field, x.from_value, x.to_value, x.actor_name, x.actor_id, x.created_at from jsonb_populate_recordset(null::public.candidate_events, d -> 'candidate_events') x
    on conflict do nothing;
  insert into public.cv_review_sessions (id, candidate_id, reviewer_name, reviewer_id, started_at, ended_at, seconds)
    select x.id, x.candidate_id, x.reviewer_name, x.reviewer_id, x.started_at, x.ended_at, x.seconds from jsonb_populate_recordset(null::public.cv_review_sessions, d -> 'cv_review_sessions') x
    on conflict do nothing;
  insert into public.candidate_reviews (id, candidate_id, stage, token, invited_at, submitted_at, overall, communication, professionalism, clarity, would_recommend, comments)
    select x.id, x.candidate_id, x.stage, x.token, x.invited_at, x.submitted_at, x.overall, x.communication, x.professionalism, x.clarity, x.would_recommend, x.comments from jsonb_populate_recordset(null::public.candidate_reviews, d -> 'candidate_reviews') x
    on conflict do nothing;
  insert into public.notifications (id, recipient_id, event, actor_name, item_count, subject, designation, detail, candidate_id, bucket_id, created_at, read_at)
    select x.id, x.recipient_id, x.event, x.actor_name, x.item_count, x.subject, x.designation, x.detail, x.candidate_id, x.bucket_id, x.created_at, x.read_at from jsonb_populate_recordset(null::public.notifications, d -> 'notifications') x
    on conflict do nothing;
  insert into public.questions (id, options, correct_option, answer, marks, difficulty, department, designation, topic, round, is_active, created_by_name, created_at, kind, question)
    select x.id, x.options, x.correct_option, x.answer, x.marks, x.difficulty, x.department, x.designation, x.topic, x.round, x.is_active, x.created_by_name, x.created_at, x.kind, x.question from jsonb_populate_recordset(null::public.questions, d -> 'questions') x
    on conflict do nothing;

  -- Requisition numbers made in the app carry on after the sample ones.
  perform setval('public.requisition_seq', greatest(
    (select coalesce(max(nullif(substring(ref_no from '\d+$'), '')::int), 0) from public.requisitions), 1));

  if shift <> 0 then
    foreach t in array array['designations', 'requisitions', 'job_postings', 'cv_buckets', 'candidates', 'candidate_events', 'cv_review_sessions', 'candidate_reviews', 'notifications', 'questions'] loop
      sample_ids := array(select (value ->> 'id')::uuid from jsonb_array_elements(d -> t));
      for c in
        select column_name, data_type from information_schema.columns
        where table_schema = 'public' and table_name = t and column_name <> 'updated_at'
          and data_type in ('date', 'timestamp with time zone')
      loop
        execute format('update public.%I set %I = %I + %s where id = any ($1)', t, c.column_name, c.column_name,
          case when c.data_type = 'date' then shift::text else format('interval %L', shift || ' days') end)
        using sample_ids;
      end loop;
    end loop;
  end if;

  raise notice 'Sample data loaded.';
end
$do$;
